
"use client";

import { useEffect, useState, type FormEvent } from "react";
import { createClient } from "@supabase/supabase-js";

const ADMIN_USER_ID = "d6d7f71f-92e7-4caa-a3cb-b09c9590b70a";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;

const supabase = createClient(supabaseUrl, supabaseAnonKey);

export default function AdminLogin() {
  const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
      const [loading, setLoading] = useState(true);
        const [submitting, setSubmitting] = useState(false);
          const [isAdmin, setIsAdmin] = useState(false);
            const [message, setMessage] = useState("");

              useEffect(() => {
                  let active = true;

                      async function checkAdmin() {
                            const { data, error } = await supabase.auth.getUser();

                                  if (!active) return;

                                        if (!error && data.user?.id === ADMIN_USER_ID) {
                                                setIsAdmin(true);
                                                      } else {
                                                              setIsAdmin(false);
                                                                    }

                                                                          setLoading(false);
                                                                              }

                                                                                  checkAdmin();

                                                                                      return () => {
                                                                                            active = false;
                                                                                                };
                                                                                                  }, []);

                                                                                                    async function handleLogin(e: FormEvent<HTMLFormElement>) {
                                                                                                        e.preventDefault();
                                                                                                            setSubmitting(true);
                                                                                                                setMessage("");

                                                                                                                    const { data, error } = await supabase.auth.signInWithPassword({
                                                                                                                          email,
                                                                                                                                password,
                                                                                                                                    });

                                                                                                                                        if (error) {
                                                                                                                                              setMessage("Login failed. Check your email and password.");
                                                                                                                                                    setSubmitting(false);
                                                                                                                                                          return;
                                                                                                                                                              }

                                                                                                                                                                  if (data.user.id !== ADMIN_USER_ID) {
                                                                                                                                                                        await supabase.auth.signOut();
                                                                                                                                                                              setMessage("Access denied. You are not an authorized admin.");
                                                                                                                                                                                    setSubmitting(false);
                                                                                                                                                                                          return;
                                                                                                                                                                                              }

                                                                                                                                                                                                  setIsAdmin(true);
                                                                                                                                                                                                      setSubmitting(false);
                                                                                                                                                                                                        }

                                                                                                                                                                                                          async function handleLogout() {
                                                                                                                                                                                                              await supabase.auth.signOut();
                                                                                                                                                                                                                  setIsAdmin(false);
                                                                                                                                                                                                                      setEmail("");
                                                                                                                                                                                                                          setPassword("");
                                                                                                                                                                                                                              setMessage("");
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                  if (loading) {
                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                            <main className="min-h-screen flex items-center justify-center bg-[#fffaf5]">
                                                                                                                                                                                                                                                    <p className="text-[#7b263c]">Loading Admin Panel...</p>
                                                                                                                                                                                                                                                          </main>
                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                      <main className="min-h-screen bg-[#fffaf5] flex items-center justify-center p-5">
                                                                                                                                                                                                                                                                            <div className="w-full max-w-md rounded-2xl bg-white p-7 shadow-xl border border-[#eadbd5]">
                                                                                                                                                                                                                                                                                    <div className="text-center mb-7">
                                                                                                                                                                                                                                                                                              <h1 className="text-3xl font-bold text-[#7b263c]">
                                                                                                                                                                                                                                                                                                          Cat&apos;s World
                                                                                                                                                                                                                                                                                                                    </h1>
                                                                                                                                                                                                                                                                                                                              <p className="text-gray-500 mt-2">Admin Control Panel</p>
                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                              {isAdmin ? (
                                                                                                                                                                                                                                                                                                                                                        <div className="text-center space-y-5">
                                                                                                                                                                                                                                                                                                                                                                    <h2 className="text-2xl font-bold text-[#7b263c]">
                                                                                                                                                                                                                                                                                                                                                                                  Welcome, Admin!
                                                                                                                                                                                                                                                                                                                                                                                              </h2>
                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-gray-600">
                                                                                                                                                                                                                                                                                                                                                                                                                        You are successfully logged in.
                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="rounded-xl bg-[#fff4ef] p-5 text-left">
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="font-semibold text-[#7b263c]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Admin Dashboard
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-sm text-gray-600 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Your admin access is active. We will add order and product
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          management next.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onClick={handleLogout}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="w-full rounded-xl bg-[#7b263c] py-3 text-white font-semibold"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Logout
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <form onSubmit={handleLogin} className="space-y-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h2 className="text-xl font-bold text-center text-gray-800">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Admin Login
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label className="block text-sm font-medium mb-2 text-gray-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Gmail
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="Enter your admin Gmail"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="w-full rounded-xl border border-gray-300 p-3 outline-none focus:border-[#7b263c] text-black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label className="block text-sm font-medium mb-2 text-gray-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Password
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={password}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setPassword(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="Enter your password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="w-full rounded-xl border border-gray-300 p-3 outline-none focus:border-[#7b263c] text-black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {message && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-sm text-red-600 text-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {message}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                disabled={submitting}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="w-full rounded-xl bg-[#7b263c] py-3 text-white font-semibold disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {submitting ? "Logging in..." : "Login to Admin"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-center text-xs text-gray-400 mt-7">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        © 2026 Cat&apos;s World. Admin Access Only.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            